# ---------------------------------------------------------------------------
# Governance Simulator — backend persistence (training-only, fail-closed).
# These routes are namespaced under /simulator/* and are completely separate
# from the control plane (/, /dashboard, /playground, /health, /api/*) and the
# runtime governance gateway. They expose the multi-backend storage adapter in
# simulator/storage.py so the Academy console can persist progress server-side
# behind the same abstraction (local | sqlite | future postgres). Any failure
# fails closed: the browser keeps using its local storage adapter.
# ---------------------------------------------------------------------------
_SIM_STORAGE_SINGLETON = None
_SIM_STORAGE_INIT_FAILED = False
_SIM_STATE_MAX_BYTES = 256 * 1024
_SIM_CLIENT_ID_CHARS = set(
    "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-"
)


def _sim_storage():
    """Lazily build the simulator storage adapter; fail closed to None."""
    global _SIM_STORAGE_SINGLETON, _SIM_STORAGE_INIT_FAILED
    if _SIM_STORAGE_SINGLETON is not None or _SIM_STORAGE_INIT_FAILED:
        return _SIM_STORAGE_SINGLETON
    try:
        from simulator.storage import get_storage_adapter

        _SIM_STORAGE_SINGLETON = get_storage_adapter()
    except Exception:
        _SIM_STORAGE_INIT_FAILED = True
        _SIM_STORAGE_SINGLETON = None
    return _SIM_STORAGE_SINGLETON


def _sim_valid_client_id(client_id: str) -> bool:
    if not client_id or len(client_id) > 64:
        return False
    return all(ch in _SIM_CLIENT_ID_CHARS for ch in client_id)


def _sim_state_key(client_id: str) -> str:
    return "sim_state_" + client_id


@app.get("/simulator/storage/health")
def simulator_storage_health():
    """Report the active simulator storage backend (fail-closed)."""
    store = _sim_storage()
    if store is None:
        return JSONResponse(
            {"ok": False, "backend": "local", "available": False,
             "writable": False, "reason": "storage_unavailable"}
        )
    try:
        health = store.health()
        health["ok"] = True
        return JSONResponse(health)
    except Exception:
        return JSONResponse(
            {"ok": False, "backend": "local", "available": False,
             "writable": False, "reason": "health_check_failed"}
        )


@app.get("/simulator/state/{client_id}")
def simulator_state_get(client_id: str):
    """Return persisted simulator state for a client, or null (fail-closed)."""
    if not _sim_valid_client_id(client_id):
        return JSONResponse({"ok": False, "reason": "invalid_client_id"}, status_code=400)
    store = _sim_storage()
    if store is None:
        return JSONResponse({"ok": False, "reason": "storage_unavailable", "state": None})
    try:
        raw = store.get(_sim_state_key(client_id))
        return JSONResponse({"ok": True, "state": json.loads(raw) if raw else None})
    except Exception:
        return JSONResponse({"ok": False, "reason": "read_failed", "state": None})


@app.put("/simulator/state/{client_id}")
async def simulator_state_put(client_id: str, request: Request):
    """Persist simulator state for a client (training-only, fail-closed)."""
    if not _sim_valid_client_id(client_id):
        return JSONResponse({"ok": False, "reason": "invalid_client_id"}, status_code=400)
    store = _sim_storage()
    if store is None:
        return JSONResponse({"ok": False, "reason": "storage_unavailable"}, status_code=503)
    try:
        body = await request.body()
    except Exception:
        return JSONResponse({"ok": False, "reason": "read_failed"}, status_code=400)
    if len(body) > _SIM_STATE_MAX_BYTES:
        return JSONResponse({"ok": False, "reason": "payload_too_large"}, status_code=413)
    try:
        # Validate it is JSON before persisting; the store keeps it opaque.
        value = body.decode("utf-8")
        json.loads(value)
    except Exception:
        return JSONResponse({"ok": False, "reason": "invalid_json"}, status_code=400)
    try:
        store.set(_sim_state_key(client_id), value)
        return JSONResponse({"ok": True, "backend": getattr(store, "backend", "local")})
    except Exception:
        return JSONResponse({"ok": False, "reason": "write_failed"}, status_code=503)


@app.delete("/simulator/state/{client_id}")
def simulator_state_delete(client_id: str):
    """Delete persisted simulator state for a client (fail-closed)."""
    if not _sim_valid_client_id(client_id):
        return JSONResponse({"ok": False, "reason": "invalid_client_id"}, status_code=400)
    store = _sim_storage()
    if store is None:
        return JSONResponse({"ok": False, "reason": "storage_unavailable"}, status_code=503)
    try:
        store.delete(_sim_state_key(client_id))
        return JSONResponse({"ok": True})
    except Exception:
        return JSONResponse({"ok": False, "reason": "delete_failed"}, status_code=503)


# ---------------------------------------------------------------------------
# Simulator voucher redemption authority (training-only, fail-closed).
# These routes are namespaced under /simulator/voucher/* and are completely
# separate from the control plane / runtime governance gateway. They sign and
# verify NON-MONETARY training vouchers using simulator/voucher.py. There is no
# payment, no booking API, no cash value, no crypto, and no cashback at any
# stage; every verification failure fails closed (valid=False).
# ---------------------------------------------------------------------------
_SIM_PARTNER_ID_CHARS = set(
    "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-"
)


def _sim_voucher_mod():
    """Import the standalone voucher authority module; fail closed to None."""
    try:
        from simulator import voucher as _voucher_mod

        return _voucher_mod
    except Exception:
        return None


def _sim_valid_partner_id(partner_id: str) -> bool:
    if not partner_id or len(partner_id) > 40:
        return False
    return all(ch in _SIM_PARTNER_ID_CHARS for ch in partner_id)


_SIM_VOUCHER_ID_CHARS = set(
    "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-"
)


def _sim_valid_voucher_id(voucher_id: str) -> bool:
    if not voucher_id or len(voucher_id) > 128:
        return False
    return all(ch in _SIM_VOUCHER_ID_CHARS for ch in voucher_id)


_SIM_REVREG_SINGLETON = None
_SIM_REVREG_INIT_FAILED = False


def _sim_revocation_registry():
    """Lazily build the central voucher revocation registry (CRL) on top of the
    simulator storage adapter. Fail closed to None if it cannot be built."""
    global _SIM_REVREG_SINGLETON, _SIM_REVREG_INIT_FAILED
    if _SIM_REVREG_SINGLETON is not None or _SIM_REVREG_INIT_FAILED:
        return _SIM_REVREG_SINGLETON
    mod = _sim_voucher_mod()
    store = _sim_storage()
    if mod is None or store is None or not hasattr(mod, "RevocationRegistry"):
        _SIM_REVREG_INIT_FAILED = True
        return None
    try:
        _SIM_REVREG_SINGLETON = mod.RevocationRegistry(store)
    except Exception:
        _SIM_REVREG_INIT_FAILED = True
        _SIM_REVREG_SINGLETON = None
    return _SIM_REVREG_SINGLETON


def _sim_to_int_or_none(raw):
    if raw is None or raw == "":
        return None
    try:
        return int(raw)
    except (TypeError, ValueError):
        return None


# Signed voucher payloads must never be cached by browsers/intermediaries.
_SIM_VOUCHER_NO_STORE = {"Cache-Control": "no-store, max-age=0"}


@app.get("/simulator/voucher/issue")
def simulator_voucher_issue(
    partner_id: str,
    client_id: str,
    ttl_days: int = 30,
    revoke: int = 0,
    approval: int = 1,
):
    """Issue a signed (training-only) voucher. The signing secret stays
    server-side. No payment / booking / cash value / crypto / cash-back. Unless
    ``approval=0`` the voucher also carries governance approval-chain evidence
    (evidence only -- it confers no money or reward)."""
    mod = _sim_voucher_mod()
    if mod is None:
        return JSONResponse({"ok": False, "reason": "authority_unavailable"}, status_code=503, headers=_SIM_VOUCHER_NO_STORE)
    if not _sim_valid_client_id(client_id):
        return JSONResponse({"ok": False, "reason": "invalid_client_id"}, status_code=400, headers=_SIM_VOUCHER_NO_STORE)
    if not _sim_valid_partner_id(partner_id):
        return JSONResponse({"ok": False, "reason": "invalid_partner_id"}, status_code=400, headers=_SIM_VOUCHER_NO_STORE)
    try:
        ttl = max(1, min(int(ttl_days), 365))
    except Exception:
        return JSONResponse({"ok": False, "reason": "invalid_ttl"}, status_code=400, headers=_SIM_VOUCHER_NO_STORE)
    try:
        with_approval = int(approval) == 1
    except Exception:
        with_approval = True
    try:
        now_ms = int(time.time() * 1000)
        revoked_at = now_ms if int(revoke) == 1 else None
        voucher_id = mod.make_voucher_id(partner_id)
        voucher = mod.issue_voucher(
            voucher_id, client_id, partner_id, ttl_days=ttl, revoked_at=revoked_at,
            with_approval=with_approval,
        )
        return JSONResponse({"ok": True, "voucher": voucher}, headers=_SIM_VOUCHER_NO_STORE)
    except Exception:
        return JSONResponse({"ok": False, "reason": "issue_failed"}, status_code=500, headers=_SIM_VOUCHER_NO_STORE)


@app.get("/simulator/voucher/verify")
def simulator_voucher_verify(
    voucher_id: str = "",
    client_id: str = "",
    partner_id: str = "",
    issued_at: str = "",
    expires_at: str = "",
    revoked_at: str = "",
    voucher_signature: str = "",
    expected_client_id: str = "",
    approval_evidence: str = "",
    enforce_approval: int = 0,
):
    """Verify a signed (training-only) voucher. Fail-closed: any tamper, missing
    field, expiry, revocation, or ownership mismatch yields valid=False. When
    ``enforce_approval=1`` the voucher must also carry valid governance
    approval-chain evidence (supplied as a JSON string in ``approval_evidence``);
    missing or malformed evidence fails closed (evidence only -- no value)."""
    mod = _sim_voucher_mod()
    fail_closed = {
        "ok": True,
        "valid": False,
        "status": "invalid",
        "reasons": ["authority_unavailable"],
        "audit_trail": [],
    }
    if mod is None:
        return JSONResponse(fail_closed, headers=_SIM_VOUCHER_NO_STORE)
    payload = {
        "voucher_id": voucher_id or None,
        "client_id": client_id or None,
        "partner_id": partner_id or None,
        "issued_at": _sim_to_int_or_none(issued_at),
        "expires_at": _sim_to_int_or_none(expires_at),
        "revoked_at": _sim_to_int_or_none(revoked_at),
        "voucher_signature": voucher_signature or None,
    }
    # Governance approval evidence (optional). When enforcement is requested we
    # parse the supplied JSON; malformed JSON fails closed as APPROVAL_INVALID and
    # an absent attestation fails closed as APPROVAL_MISSING (handled in the
    # module). The signing secret is never exposed; only the public attestation
    # is accepted from the caller.
    try:
        enforce = int(enforce_approval) == 1
    except Exception:
        enforce = False
    approval_obj = None
    approval_parse_failed = False
    if enforce and approval_evidence:
        try:
            parsed = json.loads(approval_evidence)
            approval_obj = parsed if isinstance(parsed, dict) else {"__invalid__": True}
        except Exception:
            approval_parse_failed = True
    # Verification must consult the central revocation registry (CRL). The
    # gateway always requires it: if it cannot be built we fail closed rather
    # than verify a voucher whose revocation status is unknown.
    registry = _sim_revocation_registry()
    if registry is None:
        now_ms = int(time.time() * 1000)
        fail_closed["status"] = "unavailable"
        fail_closed["reasons"] = ["REVOCATION_REGISTRY_UNAVAILABLE"]
        try:
            fail_closed["audit_trail"] = mod.redemption_audit_trail(
                payload, "unavailable", now_ms,
                reason_code="REVOCATION_REGISTRY_UNAVAILABLE")
        except Exception:
            fail_closed["audit_trail"] = []
        return JSONResponse(fail_closed, headers=_SIM_VOUCHER_NO_STORE)
    if enforce and approval_parse_failed:
        now_ms = int(time.time() * 1000)
        out = {
            "ok": True,
            "valid": False,
            "status": "invalid",
            "reasons": ["APPROVAL_INVALID"],
        }
        try:
            out["audit_trail"] = mod.redemption_audit_trail(
                payload, "invalid", now_ms, reason_code="APPROVAL_INVALID",
                approval={"ok": False, "reason": "APPROVAL_INVALID"})
        except Exception:
            out["audit_trail"] = []
        return JSONResponse(out, headers=_SIM_VOUCHER_NO_STORE)
    try:
        result = mod.verify_voucher(
            payload,
            expected_client_id=(expected_client_id or None),
            registry=registry,
            enforce_approval=enforce,
            approval=approval_obj,
        )
        result["ok"] = True
        return JSONResponse(result, headers=_SIM_VOUCHER_NO_STORE)
    except Exception:
        fail_closed["reasons"] = ["verify_error"]
        return JSONResponse(fail_closed, headers=_SIM_VOUCHER_NO_STORE)


@app.get("/simulator/voucher/redeem")
def simulator_voucher_redeem(
    voucher_id: str = "",
    client_id: str = "",
    partner_id: str = "",
    issued_at: str = "",
    expires_at: str = "",
    revoked_at: str = "",
    voucher_signature: str = "",
    expected_client_id: str = "",
    approval_evidence: str = "",
    enforce_approval: int = 0,
    action: str = "redeem",
):
    """Preview-only, partner-side voucher redemption check (PB-SIM-TRAVEL-006).

    Strictly read-only: this NEVER records a redemption, moves value, creates a
    booking or a balance, or calls a partner API. It reuses the same fail-closed
    gate as ``/verify`` and reports only whether a partner *could* honour the
    voucher. Every blocked state (revoked, expired, wrong-owner, missing/invalid
    approval, tampered signature, missing fields, unavailable registry) stays
    blocked and can never become eligible. Only a non-reversible client_ref is
    returned; the raw client id is never echoed back. ``action`` is ``redeem``
    (default) or ``preview`` and selects the audit-event vocabulary.

    Governance approval is hard-enforced on this surface regardless of any
    caller flag: a voucher with missing or invalid approval evidence can never
    be redeemable, so the ``enforce_approval`` query parameter cannot weaken the
    gate (it is accepted only for API symmetry)."""
    mod = _sim_voucher_mod()
    act = "preview" if str(action) == "preview" else "redeem"
    blocked = {
        "ok": True,
        "action": act,
        "preview_only": True,
        "partner_side": True,
        "redeemable": False,
        "valid": False,
        "redeem_state": "blocked",
        "status": "invalid",
        "reasons": ["authority_unavailable"],
        "confers_value": "none",
        "audit_trail": [],
    }
    if mod is None:
        return JSONResponse(blocked, headers=_SIM_VOUCHER_NO_STORE)
    payload = {
        "voucher_id": voucher_id or None,
        "client_id": client_id or None,
        "partner_id": partner_id or None,
        "issued_at": _sim_to_int_or_none(issued_at),
        "expires_at": _sim_to_int_or_none(expires_at),
        "revoked_at": _sim_to_int_or_none(revoked_at),
        "voucher_signature": voucher_signature or None,
    }
    # Redemption hard-enforces the governance approval gate: a voucher with
    # missing/invalid approval evidence can never be redeemable, no matter what
    # the caller passes. The ``enforce_approval`` parameter cannot weaken this.
    enforce = True
    approval_obj = None
    approval_parse_failed = False
    if approval_evidence:
        try:
            parsed = json.loads(approval_evidence)
            approval_obj = parsed if isinstance(parsed, dict) else {"__invalid__": True}
        except Exception:
            approval_parse_failed = True
    registry = _sim_revocation_registry()
    if registry is None:
        now_ms = int(time.time() * 1000)
        out = dict(blocked)
        out["status"] = "unavailable"
        out["reasons"] = ["REVOCATION_REGISTRY_UNAVAILABLE"]
        try:
            out["audit_trail"] = mod.redemption_audit_trail(
                payload, "unavailable", now_ms,
                reason_code="REVOCATION_REGISTRY_UNAVAILABLE")
        except Exception:
            out["audit_trail"] = []
        return JSONResponse(out, headers=_SIM_VOUCHER_NO_STORE)
    if enforce and approval_parse_failed:
        now_ms = int(time.time() * 1000)
        out = dict(blocked)
        out["reasons"] = ["APPROVAL_INVALID"]
        try:
            out["audit_trail"] = mod.redemption_audit_trail(
                payload, "invalid", now_ms, reason_code="APPROVAL_INVALID",
                approval={"ok": False, "reason": "APPROVAL_INVALID"})
        except Exception:
            out["audit_trail"] = []
        return JSONResponse(out, headers=_SIM_VOUCHER_NO_STORE)
    try:
        result = mod.redeem_preview(
            payload,
            action=act,
            expected_client_id=(expected_client_id or None),
            registry=registry,
            enforce_approval=enforce,
            approval=approval_obj,
        )
        return JSONResponse(result, headers=_SIM_VOUCHER_NO_STORE)
    except Exception:
        out = dict(blocked)
        out["reasons"] = ["redeem_error"]
        return JSONResponse(out, headers=_SIM_VOUCHER_NO_STORE)


@app.get("/simulator/voucher/revoke")
def simulator_voucher_revoke(
    voucher_id: str = "",
    client_id: str = "",
    reason: str = "",
    source: str = "partner_console",
    approval_evidence: str = "",
    enforce_approval: int = 0,
):
    """Revoke a voucher in the central revocation registry (CRL). Requires both
    voucher_id and client_id. Structured reason codes only; no secret is ever
    exposed. Fail-closed: if the registry is unavailable the call returns 503 and
    the voucher remains rejected on verification. When ``enforce_approval=1`` a
    valid governance approval attestation (JSON in ``approval_evidence``, bound to
    voucher_id + client_ref) is required before the revocation is recorded;
    missing or malformed evidence fails closed with 403 (evidence only)."""
    if not _sim_valid_client_id(client_id):
        return JSONResponse(
            {"ok": False, "status": "invalid", "reason_code": "INVALID_CLIENT_ID"},
            status_code=400, headers=_SIM_VOUCHER_NO_STORE)
    if not _sim_valid_voucher_id(voucher_id):
        return JSONResponse(
            {"ok": False, "status": "invalid", "reason_code": "INVALID_VOUCHER_ID"},
            status_code=400, headers=_SIM_VOUCHER_NO_STORE)
    # Governance approval gate (fail-closed). The revoke endpoint only knows the
    # voucher_id + client_id, so it cross-checks just those bound fields against
    # the authentic, self-signed attestation subject.
    try:
        enforce_rev = int(enforce_approval) == 1
    except Exception:
        enforce_rev = False
    if enforce_rev:
        mod = _sim_voucher_mod()
        if mod is None:
            return JSONResponse(
                {"ok": False, "status": "unavailable",
                 "reason_code": "REVOCATION_REGISTRY_UNAVAILABLE"},
                status_code=503, headers=_SIM_VOUCHER_NO_STORE)
        evidence = None
        if approval_evidence:
            try:
                parsed = json.loads(approval_evidence)
                evidence = parsed if isinstance(parsed, dict) else {"__invalid__": True}
            except Exception:
                return JSONResponse(
                    {"ok": False, "status": "invalid", "reason_code": "APPROVAL_INVALID"},
                    status_code=403, headers=_SIM_VOUCHER_NO_STORE)
        areason = mod.verify_approval_evidence(
            {"voucher_id": voucher_id, "client_id": client_id},
            evidence,
            bind_fields=("voucher_id", "client_ref"),
        )
        if areason:
            return JSONResponse(
                {"ok": False, "status": "invalid", "reason_code": areason},
                status_code=403, headers=_SIM_VOUCHER_NO_STORE)
    reason_clean = "".join(
        ch for ch in str(reason or "")[:120]
        if ch.isalnum() or ch in " _-."
    ).strip() or "partner_requested"
    source_clean = "".join(
        ch for ch in str(source or "")[:40]
        if ch.isalnum() or ch in "_-."
    ).strip() or "partner_console"
    registry = _sim_revocation_registry()
    if registry is None:
        return JSONResponse(
            {"ok": False, "status": "unavailable",
             "reason_code": "REVOCATION_REGISTRY_UNAVAILABLE"},
            status_code=503, headers=_SIM_VOUCHER_NO_STORE)
    try:
        out = registry.revoke(
            voucher_id, client_id, reason=reason_clean, source=source_clean)
        rec = out["record"]
        return JSONResponse(
            {
                "ok": True,
                "status": "revoked",
                "reason_code": "VOUCHER_REVOKED",
                "already_revoked": bool(out["already"]),
                "revocation": {
                    "voucher_id": rec.get("voucher_id"),
                    "client_ref": rec.get("client_ref"),
                    "reason": rec.get("reason"),
                    "revoked_at": rec.get("revoked_at"),
                    "source": rec.get("source"),
                },
            },
            headers=_SIM_VOUCHER_NO_STORE,
        )
    except Exception:
        return JSONResponse(
            {"ok": False, "status": "unavailable", "reason_code": "REVOKE_FAILED"},
            status_code=503, headers=_SIM_VOUCHER_NO_STORE)


@app.websocket("/ws/status")
async def websocket_status(websocket: WebSocket):
    await websocket.accept()
    websocket_server.register_client(websocket)
    try:
        await websocket.send_json({"type": "runtime_status", "snapshot": runtime_status_snapshot()})
        while True:
            message = await websocket.receive_text()
            if message == "ping":
                await websocket.send_json({"type": "pong", "snapshot": runtime_status_snapshot()})
            else:
                await websocket.send_json({"type": "runtime_status", "snapshot": runtime_status_snapshot()})
    except WebSocketDisconnect:
        pass
    finally:
        websocket_server.unregister_client(websocket)


@app.post("/decide")
def decide(payload: dict):
    try:
        record, reason, hydra_result = create_governance_decision(payload)
    except DecisionStoreError as exc:
        record = None
        reason = redis_failure_reason(exc)
        hydra_result = None
    except Exception:
        record = None
        reason = "decision_failed"
        hydra_result = None

    if record is None:
        audit_provenance_context = None
        try:
            audit_provenance_context = runtime_provenance_context()
        except Exception:
            audit_provenance_context = None
        if reason in {"replay_detected", "nonce_expired", "timestamp_invalid", "nonce_store_unavailable", "redis_unavailable"}:
            audit_replay_security_event(
                "nonce_store_unavailable" if reason in {"redis_unavailable"} else reason,
                payload=payload,
                provenance_context=audit_provenance_context,
            )
        try:
            audit_governance_event(
                "decision_created",
                {
                    "request_hash": request_hash(request_signature_message(payload)) if isinstance(payload, dict) else None,
                    "decision": "DENY",
                    "policy_version": _policy_version(payload) if isinstance(payload, dict) else None,
                    "nonce_hash": nonce_hash(payload.get("nonce", "")) if isinstance(payload, dict) else None,
                    "actor_hash": actor_hash(payload.get("actor_id", "")) if isinstance(payload, dict) and payload.get("actor_id") else None,
                    "reason_code": reason,
                    "policy_pubkey_id": _safe_policy_pubkey_id(audit_provenance_context),
                    "created_at": int(time.time()),
                    "expires_at": None,
                    "used": None,
                    "timestamp": int(time.time()),
                },
            )
        except Exception:
            pass
        return JSONResponse(
            status_code=403,
            content={"decision": "DENY", "decision_id": None, "reason": reason},
        )

    return {
        "decision": record["decision"],
        "decision_id": record["decision_id"],
        "request_hash": record["request_hash"],
        "expires_at": record["expires_at"],
        "expires_at_epoch": record["expires_at_epoch"],
        "decision_signature": record["decision_signature"],
        "decision_signature_classic": record["decision_signature_classic"],
        "decision_signature_pqc": record["decision_signature_pqc"],
        "alg_version": record["alg_version"],
        "actor_hash": record["actor_hash"],
        "previous_hash": record["previous_hash"],
        "audit_hash": record["audit_hash"],
        "policy_hash": record["policy_hash"],
        "policy_signature_valid": record["policy_signature_valid"],
        "signature_valid": record["signature_valid"],
        "policy_pubkey_id": record["policy_pubkey_id"],
        "policy_sequence": record["policy_sequence"],
        "policy_valid_from": record["policy_valid_from"],
        "policy_valid_until": record["policy_valid_until"],
        "reason": record["reason_code"],
        "policy_version": record["policy_version"],
        "used": bool(record.get("used", False)),
    }


@app.post("/execute")
def execute(payload: dict):
    action = payload.get("action", "unknown")
    try:
        decision_ok, decision_or_response = validate_execution_decision(payload)
    except DecisionStoreError as exc:
        return _deny_decision_response(redis_failure_reason(exc), payload=payload)
    except Exception:
        return _deny_decision_response("decision_validation_failed", payload=payload)
    if not decision_ok:
        return decision_or_response

    verification = verify(payload)

    if verification == HYDRA_DENIED:
        return JSONResponse(
            status_code=403,
            content={"error": "denied_by_hydra"},
        )

    if verification == POLICY_DENIED:
        return JSONResponse(
            status_code=403,
            content={"error": "execution_denied"},
        )

    if not verification:
        return fail_closed(action)

    # Runtime Health Authority gate (PB-RUNTIME-003): runs after the specific
    # decision/provenance/policy deny paths above (so their reason codes still
    # take precedence) and before any compute routing, so no execution can occur
    # while runtime health is FAILED, unavailable, or indeterminate. Fail closed.
    try:
        gate_allowed, gate_snapshot = runtime_execution_gate()
    except Exception:
        gate_allowed, gate_snapshot = False, {
            "state": RUNTIME_HEALTH_FAILED,
            "decision": RUNTIME_EXEC_BLOCKED,
            "execution_allowed": False,
            "reason_codes": [RHC_RUNTIME_HEALTH_AUTHORITY_ERROR],
            "audit_trail": [],
        }
    rh_decision_id = (
        str(payload.get("decision_id"))
        if isinstance(payload, dict) and payload.get("decision_id")
        else None
    )
    # PB-RUNTIME-006: record which Runtime Health Policy Profile governed this
    # decision on EVERY governed /execute call (allow OR block) so the deciding
    # profile is persistent, auditable, and can never be silently omitted from the
    # execution audit evidence. Fail-safe: never alters/blocks the decision.
    runtime_health_profile_audit_event(
        gate_snapshot, decision_id=rh_decision_id, action=action)

    if not gate_allowed:
        return runtime_health_block_response(
            gate_snapshot, decision_id=rh_decision_id, action=action)

    # PB-RUNTIME-004: DEGRADED is allowed (warning-only) but must not proceed
    # silently -- leave an explicit, audited warning record. This never blocks.
    if isinstance(gate_snapshot, dict) and gate_snapshot.get("state") == RUNTIME_HEALTH_DEGRADED:
        runtime_health_degraded_warning_event(
            gate_snapshot, decision_id=rh_decision_id, action=action)

    try:
        execution_proof = route_execution(payload, decision_or_response)
    except ComputeRoutingError as exc:
        return _deny_decision_response(
            str(exc) or "compute_routing_failed",
            payload=payload,
            decision_id=str(payload.get("decision_id")),
        )
    except Exception:
        return _deny_decision_response(
            "compute_routing_failed",
            payload=payload,
            decision_id=str(payload.get("decision_id")),
        )

    try:
        decision_used = mark_decision_used(decision_or_response, execution_proof=execution_proof)
    except DecisionStoreError as exc:
        return _deny_decision_response(
            redis_failure_reason(exc),
            payload=payload,
            decision_id=str(payload.get("decision_id")),
        )
    except Exception:
        return _deny_decision_response(
            "decision_use_failed",
            payload=payload,
            decision_id=str(payload.get("decision_id")),
        )

    if not decision_used:
        return _deny_decision_response(
            "replay_detected",
            payload=payload,
            decision_id=str(payload.get("decision_id")),
        )

    decision_or_response["used"] = True
    try:
        audit_chain.append(
            action,
            {
                "decision": "ALLOW",
                "tenant_id": decision_or_response.get("tenant_id"),
                "tenant_hash": decision_or_response.get("tenant_hash"),
                "policy_hash": decision_or_response.get("policy_hash"),
                "node_id": decision_or_response.get("gateway_id"),
            },
        )
        audit_governance_event(
            "execution_allowed",
            {
                **decision_or_response,
                "reason_code": "decision_used",
                **execution_proof,
                "timestamp": int(time.time()),
            },
        )
    except Exception:
        return fail_closed(action)

    return {"status": "EXECUTED"}


@app.get("/policy/version")
def policy_version():
    try:
        registry = load_policy_registry(provenance_context=runtime_provenance_context())
    except Exception:
        return JSONResponse(
            status_code=503,
            content={"error": "policy_registry_unavailable"},
        )
    return {
        "version": registry["version"],
        "policy_version": registry["version"],
        "last_updated": registry["last_updated"],
        "authority": registry["authority"],
        "policy_signature_valid": registry["policy_signature_valid"],
        "policy_pubkey_id": registry["policy_pubkey_id"],
        "policy_sequence": registry["policy_sequence"],
        "policy_hash": registry["policy_hash"],
        "valid_from": registry["valid_from"],
        "valid_until": registry["valid_until"],
    }


@app.get("/policy/state")
def policy_state():
    mode, reason, registry = policy_runtime_state(provenance_context=runtime_provenance_context())
    if registry is None:
        return JSONResponse(
            status_code=503,
            content={
                "mode": "FAIL_CLOSED",
                "reason": reason,
                "policy_signature_valid": False,
            },
        )
    return {
        "mode": mode,
        "reason": reason,
        "policy_state": "valid" if mode == "NORMAL" else "degraded",
        "policy_version": registry["version"],
        "policy_hash": registry["policy_hash"],
        "policy_pubkey_id": registry["policy_pubkey_id"],
        "policy_signature_valid": registry["policy_signature_valid"],
        "policy_sequence": registry["policy_sequence"],
    }


# ---------------------------------------------------------------------------
# Governance Runtime Health Authority (PB-RUNTIME-001)
#
# A single, fail-closed authority that continuously validates the health of the
# core governance runtime subsystems and decides whether execution paths may
# proceed BEFORE a user action is processed:
#
#     HEALTHY  -> execution allowed
#     DEGRADED -> execution allowed, warning surfaced + explicitly audited
#     FAILED   -> execution blocked
#
# The authority itself fails closed: any unexpected error collapses to FAILED so
# a broken gateway can never present itself as healthy. It is read-only -- every
# probe is a non-mutating reachability/self-test against an existing subsystem.
#
# DEGRADED policy decision (PB-RUNTIME-004):
#   DEGRADED is, by canonical policy, WARNING-ONLY -- it does NOT fail closed.
#   This is a deliberate contract, not an oversight: a DEGRADED subsystem is one
#   that is still serving correctly but has a non-fatal integrity/reachability
#   signal worth surfacing (e.g. audit hash-chain verification could not be
#   re-confirmed, runtime storage is read-only, policy engine is in a non-NORMAL
#   but loadable mode). Blocking every governed execution on such a signal would
#   convert a soft observability warning into a hard outage and incentivise
#   operators to silence probes -- the opposite of the safety goal. Only FAILED
#   (subsystem unavailable / authority error / probe exception) blocks. The
#   warning-only behavior is pinned by tests (test_runtime_health_degraded_*),
#   which constitute the product contract. To keep DEGRADED from proceeding
#   SILENTLY, every DEGRADED execution emits an explicit, audited warning event
#   carrying RHC_RUNTIME_HEALTH_DEGRADED_WARNING (see
#   runtime_health_degraded_warning_event); promoting DEGRADED to fail-closed is
#   a future product decision, not a bug to patch here.
# ---------------------------------------------------------------------------
RUNTIME_HEALTH_SCHEMA = "usbay.runtime_health.v1"

RUNTIME_HEALTH_HEALTHY = "HEALTHY"
RUNTIME_HEALTH_DEGRADED = "DEGRADED"
RUNTIME_HEALTH_FAILED = "FAILED"

# Execution decisions derived from the canonical health state.
RUNTIME_EXEC_ALLOWED = "EXECUTION_ALLOWED"
RUNTIME_EXEC_WARNING = "EXECUTION_ALLOWED_WITH_WARNING"
RUNTIME_EXEC_BLOCKED = "EXECUTION_BLOCKED"

# Health reason codes (stable, machine-readable).
RHC_POLICY_ENGINE_UNAVAILABLE = "POLICY_ENGINE_UNAVAILABLE"
RHC_POLICY_ENGINE_DEGRADED = "POLICY_ENGINE_DEGRADED"
RHC_AUDIT_SUBSYSTEM_UNAVAILABLE = "AUDIT_SUBSYSTEM_UNAVAILABLE"
RHC_AUDIT_CHAIN_INVALID = "AUDIT_CHAIN_INVALID"
RHC_RUNTIME_STORAGE_UNAVAILABLE = "RUNTIME_STORAGE_UNAVAILABLE"
RHC_RUNTIME_STORAGE_NOT_WRITABLE = "RUNTIME_STORAGE_NOT_WRITABLE"
RHC_APPROVAL_SUBSYSTEM_UNAVAILABLE = "APPROVAL_SUBSYSTEM_UNAVAILABLE"
RHC_APPROVAL_SELFTEST_FAILED = "APPROVAL_SELFTEST_FAILED"
RHC_REVOCATION_SUBSYSTEM_UNAVAILABLE = "REVOCATION_SUBSYSTEM_UNAVAILABLE"
RHC_REVOCATION_SUBSYSTEM_DEGRADED = "REVOCATION_SUBSYSTEM_DEGRADED"
RHC_RUNTIME_HEALTH_AUTHORITY_ERROR = "RUNTIME_HEALTH_AUTHORITY_ERROR"
RHC_RUNTIME_HEALTH_EXECUTION_BLOCKED = "RUNTIME_HEALTH_EXECUTION_BLOCKED"
# PB-RUNTIME-004: stable reason code attached to the explicit audit record left
# whenever a governed execution proceeds under DEGRADED (warning-only) health.
RHC_RUNTIME_HEALTH_DEGRADED_WARNING = "RUNTIME_HEALTH_DEGRADED_WARNING"

# PB-RUNTIME-005: Runtime Health Policy Profiles -- DEGRADED handling is governed
# by a named profile instead of hardcoded logic. FAILED (and authority/probe/gate
# failures that collapse to FAILED) block in EVERY profile; only the DEGRADED
# branch differs. BALANCED is the default and preserves the PB-RUNTIME-004
# contract (DEGRADED -> warning-only). A misconfigured/unknown profile value
# fails closed to STRICT (the most restrictive profile).
