    {n:"Isabella Rossi",r:"Hotel Concierge",reg:"South Europe - Italy",pr:"she/her",t:"t1",tags:["Hotel"]},
    {n:"Diego Santos",r:"Human Review Officer",reg:"South America - Brazil",pr:"they/them",t:"t2",tags:["Governance","Human Review"]}
